diff --git a/lib/parsedate.c b/lib/parsedate.c
index b4dd97bb7f..62c81a4613 100644
--- a/lib/parsedate.c
+++ b/lib/parsedate.c
@@ -114,7 +114,7 @@ struct tzinfo {

 #define tDAYZONE (-60)         /* offset for daylight savings time */

-/* alpha-sorted list of single-letter time zones */
+/* alpha-sorted list of single-letter time zones, no entry for J */
 static const struct tzinfo tzone[] = {
   { "A", -1 * 60 },            /* Alpha */
   { "B", -2 * 60 },            /* Bravo */
@@ -125,7 +125,6 @@ static const struct tzinfo tzone[] = {
   { "G", -7 * 60 },            /* Golf */
   { "H", -8 * 60 },            /* Hotel */
   { "I", -9 * 60 },            /* India */
-  { "", -1 },          /* not a timezone */
   { "K", -10 * 60 },           /* Kilo */
   { "L", -11 * 60 },           /* Lima */
   { "M", -12 * 60 },           /* Mike */
@@ -337,7 +336,8 @@ UNITTEST int checktz(const char *check, size_t len)
     /* short-cut single letter names */
     if((check[0] < 'A') || (check[0] > 'Z') || (check[0] == 'J'))
       return -1; /* no such tz */
-    return tzone[check[0] - 'A'].offset * 60;
+    /* there is no entry for J, skip its slot */
+    return tzone[check[0] - 'A' - (check[0] > 'J')].offset * 60;
   }
   else if(len == 2) {
     /* two-letter names */
